-- GATE PACK 0255 policies (POST-APPLY read-back). Read-only catalog SELECT, no writes, no table data. Generated by gate-packs/mkpacks.py; do not edit by hand.
select tablename as obj, policyname, cmd, permissive, array_to_string(roles, ',') as roles
from pg_catalog.pg_policies
where schemaname = 'public' and tablename in ('waitlist', 'demo_requests')
order by 1, 2;
